import {parseGLB,worldMatrices,multiply,lookAt,orthographic,normals,identity} from './model3d.js';
const vertex=`attribute vec3 aPosition;attribute vec3 aNormal;uniform mat4 uWorld;uniform mat4 uVP;uniform mat3 uNormal;varying vec3 vNormal;varying vec3 vPosition;void main(){vec4 p=uWorld*vec4(aPosition,1.0);vPosition=p.xyz;vNormal=uNormal*aNormal;gl_Position=uVP*p;}`;
const fragment=`precision mediump float;uniform vec4 uColor;uniform float uRough;uniform vec3 uEye;varying vec3 vNormal;varying vec3 vPosition;void main(){vec3 n=normalize(vNormal);vec3 key=normalize(vec3(-2.0,3.0,4.0));float light=0.3+0.62*max(dot(n,key),0.0)+0.22*max(dot(n,normalize(vec3(3.0,1.0,-2.0))),0.0);vec3 eye=normalize(uEye-vPosition);float spec=pow(max(dot(n,normalize(key+eye)),0.0),mix(60.0,8.0,uRough))*(1.0-uRough)*0.16;gl_FragColor=vec4(pow(max(uColor.rgb*light+spec,vec3(0.0)),vec3(0.454545)),uColor.a);}`;
export class Hamster3D{
 constructor(canvas=document.createElement('canvas')){
  this.canvas=canvas;canvas.width=canvas.height=256;this.gl=canvas.getContext('webgl',{alpha:true,antialias:true,premultipliedAlpha:true,preserveDrawingBuffer:true});if(!this.gl)throw Error('WebGL unavailable');
  this.lost=false;canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();this.lost=true;});canvas.addEventListener('webglcontextrestored',()=>{try{this.setup();this.upload();this.lost=false;}catch{this.lost=true;}});
  this.vp=multiply(orthographic(-.95,.95,-.95,.95,.1,10),lookAt([0,1.15,4],[0,.46,0]));this.setup();
 }
 setup(){this.generation=(this.generation||0)+1;const gl=this.gl;const compile=(type,source)=>{const shader=gl.createShader(type);gl.shaderSource(shader,source);gl.compileShader(shader);if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(shader));return shader;};const v=compile(gl.VERTEX_SHADER,vertex),f=compile(gl.FRAGMENT_SHADER,fragment),program=gl.createProgram();gl.attachShader(program,v);gl.attachShader(program,f);gl.linkProgram(program);gl.deleteShader(v);gl.deleteShader(f);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));this.program=program;this.attributes={position:gl.getAttribLocation(program,'aPosition'),normal:gl.getAttribLocation(program,'aNormal')};this.uniforms=Object.fromEntries(['uWorld','uVP','uNormal','uColor','uRough','uEye'].map(k=>[k,gl.getUniformLocation(program,k)]));gl.enable(gl.DEPTH_TEST);gl.enable(gl.CULL_FACE);gl.cullFace(gl.BACK);gl.clearColor(0,0,0,0);}
 async load(url=new URL('../assets/hamster.glb',import.meta.url)){const response=await fetch(url);if(!response.ok)throw Error('Cannot load hamster model');this.model=parseGLB(await response.arrayBuffer());this.upload();return this;}
 uploadMesh(p){const gl=this.gl,buffer=(data,type)=>{const b=gl.createBuffer();gl.bindBuffer(type,b);gl.bufferData(type,data,gl.STATIC_DRAW);return b;};if(p.indices instanceof Uint32Array&&!gl.getExtension('OES_element_index_uint'))throw Error('32-bit indices unavailable');return {position:buffer(p.positions,gl.ARRAY_BUFFER),normal:buffer(p.normals,gl.ARRAY_BUFFER),index:buffer(p.indices,gl.ELEMENT_ARRAY_BUFFER),count:p.indices.length,type:p.indices instanceof Uint32Array?gl.UNSIGNED_INT:p.indices instanceof Uint8Array?gl.UNSIGNED_BYTE:gl.UNSIGNED_SHORT,material:p.material||{}};}
 upload(){if(this.model)this.meshes=this.model.meshes.map(mesh=>mesh.map(p=>this.uploadMesh(p)));}
 deleteMesh(p){for(const key of ['position','normal','index'])this.gl.deleteBuffer(p[key]);}
 beginFrame({width=this.canvas.width,height=this.canvas.height,vp=this.vp,eye=[0,1.15,4],background=[0,0,0,0]}={}){const gl=this.gl;if(this.canvas.width!==width||this.canvas.height!==height){this.canvas.width=width;this.canvas.height=height;}gl.viewport(0,0,width,height);gl.clearColor(...background);gl.depthMask(true);gl.disable(gl.BLEND);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(this.program);gl.uniformMatrix4fv(this.uniforms.uVP,false,vp);gl.uniform3fv(this.uniforms.uEye,eye);}
 drawMesh(p,world,coat=null){const gl=this.gl;gl.uniformMatrix4fv(this.uniforms.uWorld,false,world);gl.uniformMatrix3fv(this.uniforms.uNormal,false,normals(world));for(const [key,b]of [['position',p.position],['normal',p.normal]]){gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.enableVertexAttribArray(this.attributes[key]);gl.vertexAttribPointer(this.attributes[key],3,gl.FLOAT,false,0,0);}const pbr=p.material.pbrMetallicRoughness||{};let color=pbr.baseColorFactor||[1,1,1,1];if(p.material.name==='Golden fur'&&coat&&coat!=='golden')color=coat==='snow'?[.8,.78,.71,1]:[.28,.33,.36,1];gl.uniform4fv(this.uniforms.uColor,color);gl.uniform1f(this.uniforms.uRough,pbr.roughnessFactor??.85);if(p.material.doubleSided)gl.disable(gl.CULL_FACE);else gl.enable(gl.CULL_FACE);gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,p.index);gl.drawElements(gl.TRIANGLES,p.count,p.type,0);}
 drawModel(state,time,{yaw=(state.pet.direction||1)*1.05,moving=false,base=identity()}={}){for(const [i,matrix]of worldMatrices(this.model,state,time,yaw,moving)){const node=this.model.doc.nodes[i];if(node.mesh===undefined)continue;const world=multiply(base,matrix);for(const p of this.meshes[node.mesh])this.drawMesh(p,world,state.coat);}}
 render(state,time,options={}){if(!this.model||this.lost||this.gl.isContextLost())return null;this.beginFrame();this.drawModel(state,time,options);return this.canvas;}
 dispose(){const gl=this.gl;for(const mesh of this.meshes||[])for(const p of mesh)for(const key of ['position','normal','index'])gl.deleteBuffer(p[key]);gl.deleteProgram(this.program);}
}
